# JSF checks for nbkit (loaded by nbkit.sh with source).
# Installs the nbkit.jsf module in NetBeans: warnings in the xhtml editor (EL, ids, forms, templates...),
# with the same colors as the Java warnings. Each rule toggles in Tools > Options > Editor > JSF.
# The texts inside NetBeans follow the system language (Bundle.properties / Bundle_pt.properties in the jar).

nbkit_register jsf jsf tool "$(t jsf.name)" "$(t jsf.description)" 2

jsf_jar() { echo "$UD/modules/nbkit-jsf.jar"; }
jsf_xml() { echo "$UD/config/Modules/nbkit-jsf.xml"; }

jsf_status() {
  if [ -e "$(jsf_jar)" ]; then version_status jsf; else echo no; fi
}

jsf_paths() {
  printf '%s\n' modules/nbkit-jsf.jar config/Modules/nbkit-jsf.xml
}

jsf_install_steps() { echo 1; }
jsf_uninstall_steps() { echo 1; }

jsf_uninstall_summary() {
  t jsf.summary_out; echo
  t jsf.summary_stays; echo
}

jsf_install() {
  local jar xml
  jar="$(jsf_jar)"; xml="$(jsf_xml)"
  step "$(t jsf.step_install)"
  mkdir -p "$UD/modules" "$UD/config/Modules"
